module asyn_fifo #(
    parameter	WIDTH = 8,
    parameter 	DEPTH = 16,
    parameter ADDR_WIDTH = $clog2(DEPTH)
) (
    input 					wclk,
    input 					rclk,
    input 					wrstn,
    input					rrstn,
    input 					winc,
    input 			 		rinc,
    input 		[WIDTH-1:0]	wdata,
    output wire				wfull,
    output wire				rempty,
    output wire [WIDTH-1:0]	rdata
);

reg [WIDTH-1:0] ram_mem[DEPTH-1:0];
reg [WIDTH-1:0] rdata_reg;
reg [ADDR_WIDTH:0] waddr_bin;
reg [ADDR_WIDTH:0] raddr_bin;
reg [ADDR_WIDTH:0] wptr;
reg [ADDR_WIDTH:0] rptr;
reg [ADDR_WIDTH:0] wptr_buff;
reg [ADDR_WIDTH:0] rptr_buff;
reg [ADDR_WIDTH:0] wptr_syn;
reg [ADDR_WIDTH:0] rptr_syn;
reg wen;
reg ren;

function [ADDR_WIDTH:0] bin_to_gray(input [ADDR_WIDTH:0] bin);
begin
    bin_to_gray = {bin[ADDR_WIDTH], bin[ADDR_WIDTH-1:0] ^ bin[ADDR_WIDTH:1]};
end
endfunction

function [ADDR_WIDTH:0] gray_to_bin(input [ADDR_WIDTH:0] gray);
begin
    gray_to_bin[ADDR_WIDTH] = gray[ADDR_WIDTH];
    gray_to_bin[ADDR_WIDTH-1:0] = gray[ADDR_WIDTH:1] ^ gray[ADDR_WIDTH-1:0];
end
endfunction

reg [WIDTH-1:0] RAM_MEM [0:DEPTH-1];

always @(posedge wclk) begin
    if (wen)
        RAM_MEM[waddr_bin[ADDR_WIDTH-1:0]] <= wdata;
end

always @(posedge rclk) begin
    if (ren)
        rdata_reg <= RAM_MEM[raddr_bin[ADDR_WIDTH-1:0]];
end

always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        waddr_bin <= 0;
    end else if (winc && !wfull) begin
        waddr_bin <= waddr_bin + 1;
    end
end

always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        raddr_bin <= 0;
    end else if (rinc && !rempty) begin
        raddr_bin <= raddr_bin + 1;
    end
end

always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        wptr <= 0;
    end else begin
        wptr <= bin_to_gray(waddr_bin);
    end
end

always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        rptr <= 0;
    end else begin
        rptr <= bin_to_gray(raddr_bin);
    end
end

always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        wptr_buff <= 0;
    end else begin
        wptr_buff <= wptr;
    end
end

always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        rptr_buff <= 0;
    end else begin
        rptr_buff <= rptr;
    end
end

always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        wptr_syn <= 0;
    end else begin
        wptr_syn <= wptr_buff;
    end
end

always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        rptr_syn <= 0;
    end else begin
        rptr_syn <= rptr_buff;
    end
end

always @(*) begin
    wen = winc & !wfull;
end

always @(*) begin
    ren = rinc & !rempty;
end

assign wfull = (wptr == {~rptr_syn[ADDR_WIDTH:ADDR_WIDTH-1], rptr_syn[ADDR_WIDTH-2:0]});
assign rempty = (rptr == wptr_syn);
assign rdata = rdata_reg;

endmodule

module dual_port_RAM #(parameter DEPTH = 16,  parameter WIDTH = 8)
(
	 input wclk	,
	 input wenc	,
	 input [$clog2(DEPTH)-1:0] waddr  ,
	 input [WIDTH-1:0] wdata ,
	 input rclk	,
	 input renc	,
	 input [$clog2(DEPTH)-1:0] raddr ,
	 output reg [WIDTH-1:0] rdata 		
);

reg [WIDTH-1:0] RAM_MEM [0:DEPTH-1];

always @(posedge wclk) begin
	if(wenc)
		RAM_MEM[waddr] <= wdata;
end 

always @(posedge rclk) begin
	if(renc)
		rdata <= RAM_MEM[raddr];
end 

endmodule
